    #[inductive(reader_finish)]
    fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
        assert(pre.combiner[node_id].is_Reading());
        assert(pre.combiner[node_id].get_Reading_0().is_Range());
        let rs = pre.combiner[node_id].get_Reading_0();
        assert(pre.reader_state_valid(node_id, rs));
        assert(rs.get_Range_start() == pre.local_versions[node_id]);
        assert(rs.get_Range_cur() == rs.get_Range_end());
        assert(rs.get_Range_start() <= rs.get_Range_end());
        assert(post.local_versions[node_id] == rs.get_Range_end());

        assert forall |i: int|
            post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                + post.buffer_size
            implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
            assert(post.tail == pre.tail);
            assert(post.buffer_size == pre.buffer_size);
            assert(post.alive_bits == pre.alive_bits);
            assert(post.num_replicas == pre.num_replicas);
            assert forall |n: nat| 0 <= n < post.num_replicas
                implies pre.local_versions.contains_key(n)
                    && post.local_versions.contains_key(n) by { }
            assert forall |n: nat| 0 <= n < post.num_replicas
                implies pre.local_versions[n] <= post.local_versions[n] by {
                if n == node_id {
                    assert(pre.local_versions[n] == rs.get_Range_start());
                    assert(post.local_versions[n] == rs.get_Range_end());
                } else {
                    assert(pre.local_versions[n] == post.local_versions[n]);
                }
            }
            map_min_value_monotonic(pre.local_versions, post.local_versions,
                (post.num_replicas - 1) as nat);
            assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                >= map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));
            assert(pre.tail <= i);
            assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
        }

        assert forall |i: int|
            post.tail - post.buffer_size <= i < post.tail
            implies (log_entry_is_alive(post.alive_bits, i, post.buffer_size)
                || i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
                <==> post.contents.contains_key(i) by {
            assert(post.tail == pre.tail);
            assert(post.buffer_size == pre.buffer_size);
            assert(post.alive_bits == pre.alive_bits);
            assert(post.contents == pre.contents);
            assert(post.num_replicas == pre.num_replicas);
            assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                >= map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));
        }
    }

    #[inductive(reader_abort)]
    fn reader_abort_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }
}}

