display.text:
    assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
        >= map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));
    assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
        <= post.local_versions[node_id]);
    let old_min = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
    map_min_value_smallest(pre.local_versions, (pre.num_replicas - 1) as nat);
    assert(map_contains_value(pre.local_versions, old_min));
    let min_node = choose|n: NodeId| pre.local_versions.contains_key(n)
        && pre.local_versions[n] == old_min;
    assert(pre.local_versions.contains_key(min_node));
    assert(pre.local_versions[min_node] == old_min);
    assert(0 <= min_node < pre.num_replicas);
    assert(pre.tail <= old_min + pre.buffer_size);
    if old_min < rs.get_Range_start() {
        assert(min_node != node_id);
        assert(post.local_versions[min_node] == pre.local_versions[min_node]);
        assert(0 <= min_node < post.num_replicas);
        assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
            <= post.local_versions[min_node]);
        assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
            == old_min);
    }

    assert forall |i: int|
        post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
            + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        assert(pre.tail <= i);
        if old_min < rs.get_Range_start() {
            assert(min_node != node_id);
            assert(post.local_versions[min_node] == pre.local_versions[min_node]);
            map_min_value_smallest(post.local_versions, (post.num_replicas - 1) as nat);
            assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                <= post.local_versions[min_node]);
            assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                == old_min);
            assert(i < old_min + pre.buffer_size);
            assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
        } else {
            assert(old_min == rs.get_Range_start());
            if i < old_min + pre.buffer_size {
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            } else {
                let j = i - pre.buffer_size;
                assert(old_min <= j < rs.get_Range_end());
                assert(log_entry_is_alive(pre.alive_bits, j, pre.buffer_size));
                log_entry_alive_wrap_around(pre.alive_bits, pre.buffer_size,
                    rs.get_Range_start(), rs.get_Range_end());
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            }
        }
    }

    assert forall |i: int|
        post.tail - post.buffer_size <= i < post.tail
        implies (log_entry_is_alive(post.alive_bits, i, post.buffer_size)
            || i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
            <==> post.contents.contains_key(i) by {
        assert(post.contents == pre.contents);
        assert(i < old_min + pre.buffer_size);
        assert(pre.inv_buffer_contents());
        assert((log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
            || i < old_min) <==> pre.contents.contains_key(i));
        if i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat) {
            if old_min < rs.get_Range_start() {
                assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                    == old_min);
                assert(false);
            } else {
                assert(i < rs.get_Range_end());
                assert(pre.contents.contains_key(i));
            }
        }
    }
}

